void CortexEditor::choosePreset(bool saving){
 if(saving&&processor.exportUserPreset(presetName.getText()).isEmpty()){presetStatus.setText("Enter a preset name (1–80 characters).",juce::dontSendNotification);return;}
 auto initial=juce::File::getSpecialLocation(juce::File::userDocumentsDirectory);if(saving)initial=initial.getChildFile(juce::File::createLegalFileName(presetName.getText().trim())+".cortex65.json");presetChooser=std::make_unique<juce::FileChooser>(saving?"Save CORTEX 65 preset":"Load CORTEX 65 preset",initial,"*.json");saveUser.setEnabled(false);loadUser.setEnabled(false);juce::Component::SafePointer<CortexEditor> safe(this);int flags=juce::FileBrowserComponent::canSelectFiles|(saving?juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::warnAboutOverwriting:juce::FileBrowserComponent::openMode);
 presetChooser->launchAsync(flags,[safe,saving](const juce::FileChooser& chooser){if(!safe||safe->closing)return;safe->saveUser.setEnabled(true);safe->loadUser.setEnabled(true);auto file=chooser.getResult();if(file==juce::File())return;juce::String error,name;bool ok=saving?safe->processor.saveUserPresetFile(file,safe->presetName.getText(),error):safe->processor.loadUserPresetFile(file,name,error);if(ok&&!saving)safe->presetName.setText(name);safe->presetStatus.setText(ok?(saving?"Preset saved.":"Preset loaded."):error,juce::dontSendNotification);});
}
