void CortexEditor::projectPoints(){float cy=std::cos(yaw),sy=std::sin(yaw),cp=std::cos(pitch),sp=std::sin(pitch);float size=std::min(brain.getWidth()*.47f/(.78f+.45f*displaySpread),brain.getHeight()*.49f);for(int i=0;i<CortexProcessor::visualCount;++i){auto p=points[i];float outward=cortex::spreadX(p.x,i<32768?0:1,displaySpread);float x=outward*cy+p.z*sy,z=-outward*sy+p.z*cy,y=p.y*cp-z*sp;float depth=p.y*sp+z*cp;float nx=p.nx*cy+p.nz*sy,nz=-p.nx*sy+p.nz*cy,ny=p.ny*cp-nz*sp;float nz2=p.ny*sp+nz*cp;float lighting=.22f+.78f*std::abs(.20f*nx-.28f*ny+.94f*nz2);projected[i]={brain.getCentreX()+x*size,brain.getCentreY()-y*size,depth,juce::jlimit(.12f,1.f,lighting)};}std::sort(drawOrder.begin(),drawOrder.end(),[&](int a,int b){return projected[a].z<projected[b].z;});}
void CortexEditor::timerCallback(){processor.copyVisual(phases);float targetSpread=processor.param("spread");if(std::abs(targetSpread-displaySpread)>.0001f){displaySpread+=.22f*(targetSpread-displaySpread);projectPoints();}bool orbit=processor.param("orbitEnabled")>.5f;if(orbit&&processor.param("binaural")>.5f)processor.state.getParameter("binaural")->setValueNotifyingHost(0);bool pairs=processor.param("binaural")>.5f&&!orbit;headOrbit.setButtonText(orbit?"HEAD ORBIT / ON":"HEAD ORBIT / OFF");binaural.setButtonText(pairs?"BINAURAL / ON":"BINAURAL / OFF");for(int i:{7,8}){bool enabled=!pairs&&(i!=8||!orbit);sliders[i].setEnabled(enabled);labels[i].setEnabled(enabled);}for(int i=0;i<3;++i)voices.changeItemText(i+1,juce::String(4<<i)+(pairs?" PAIRS":" VOICES"));field.setButtonText(processor.param("field")>.5f?"PAUSE FIELD":"START FIELD");pulses.setButtonText(processor.param("pulses")>.5f?"PULSES / ON":"PULSES / OFF");for(int i=0;i<16;++i){auto serial=processor.pulseCounters[i].load();flashes[i]*=.80f;if(serial!=seenVisualPulses[i]&&processor.pulseEpoch[i].load()==processor.activityEpoch.load()){flashes[i]=1;selected=i;}seenVisualPulses[i]=serial;}repaint();rackPanel.repaint();}
void CortexEditor::mouseDown(const juce::MouseEvent& e){if(brain.contains(e.position)){dragStart=e.position;dragYaw=yaw;dragPitch=pitch;dragged=false;}}
void CortexEditor::mouseDrag(const juce::MouseEvent& e){if(!brain.contains(dragStart))return;auto delta=e.position-dragStart;if(delta.getDistanceFromOrigin()>4)dragged=true;if(dragged){yaw=dragYaw+delta.x*.004f;pitch=juce::jlimit(-1.1f,1.1f,dragPitch+delta.y*.004f);projectPoints();repaint();}}
void CortexEditor::mouseUp(const juce::MouseEvent& e){if(!dragged&&brain.contains(e.position))exciteAt(e.position);}
void CortexEditor::exciteAt(juce::Point<float> at){float best=1e20f;int index=0;for(int i=0;i<CortexProcessor::visualCount;++i){auto p=projected[i];float distance=(p.x-at.x)*(p.x-at.x)+(p.y-at.y)*(p.y-at.y);if(distance<best){best=distance;index=i;}}selected=index/4096;processor.seedNode(index);flashes[selected]=1;}
