void CortexEditor::renderBrain(){
 if(!brainImage.isValid())return;
 juce::Image::BitmapData pixels(brainImage,juce::Image::BitmapData::writeOnly);
 for(int y=0;y<pixels.height;++y)std::memset(pixels.getLinePointer(y),0,size_t(pixels.width)*4);
 std::array<float,16> ages{},radii{},strengths{},releaseAt{};std::array<int,16> sources{},notes{};for(int g=0;g<16;++g){ages[g]=processor.eventAge[g].load();radii[g]=std::max(.000001f,processor.eventRadius[g].load());strengths[g]=processor.eventStrength[g].load();sources[g]=juce::jlimit(0,65535,processor.eventSource[g].load());notes[g]=processor.eventNote[g].load();releaseAt[g]=processor.eventReleaseAt[g].load();}
 float a=processor.param("attack"),d=processor.param("decay"),s=processor.param("sustain"),r=processor.param("release");
 for(int index:drawOrder){const auto p=projected[index];int region=index/4096;const auto origin=points[sources[region]],point=points[index];float dx=point.x-origin.x,dy=point.y-origin.y,dz=point.z-origin.z;float normalizedDistance=std::sqrt(dx*dx+dy*dy+dz*dz)/radii[region];float arrival=a*normalizedDistance;float hit=strengths[region]*cortex::visualEnvelope(ages[region],arrival,a,d,s,r,notes[region]>=0,releaseAt[region]);if(normalizedDistance<.035f&&ages[region]<.08f)hit=std::max(hit,strengths[region]*(1-ages[region]/.08f));float phase=phases[index],phaseLight=.55f+.45f*std::cos(phase);float front=.45f+.55f*juce::jlimit(0.f,1.f,(p.z+.65f)/1.3f);float opacity=juce::jlimit(.06f,1.f,(.35f+.65f*p.light)*front*(.65f+.35f*phaseLight)+hit*.4f);auto color=cyan.interpolatedWith(mint,.35f+.35f*std::sin(phase)).interpolatedWith(amber,juce::jlimit(0.f,1.f,hit*1.25f));int x=int(std::floor(p.x)),y=int(std::floor(p.y));if(x<0||x+1>=pixels.width||y<0||y+1>=pixels.height)continue;float fx=p.x-x,fy=p.y-y;
  for(int dy=0;dy<2;++dy)for(int dx=0;dx<2;++dx){float weight=(dx?fx:1-fx)*(dy?fy:1-fy);auto alpha=juce::uint8(juce::jlimit(0.f,255.f,opacity*weight*(1.7f+hit*.6f)*255));juce::PixelARGB source;source.setARGB(alpha,color.getRed(),color.getGreen(),color.getBlue());source.premultiply();reinterpret_cast<juce::PixelARGB*>(pixels.getPixelPointer(x+dx,y+dy))->blend(source);}
 }
}
