 g.setColour(cyan);g.setFont(mono(19));g.drawText("R",28,getHeight()/2,30,25,juce::Justification::centredLeft);g.drawText("L",split-55,getHeight()/2,30,25,juce::Justification::centredRight);g.setColour(muted);g.setFont(mono(10));g.drawText("DRAG TO ROTATE / CLICK TO EXCITE",split-385,getHeight()-115,355,18,juce::Justification::centredRight);g.drawText("BodyParts3D / DBCLS / CC BY 4.0",28,getHeight()-115,320,18,juce::Justification::centredLeft);
